 DRY-RUN strict par défaut (v0.3.3.1).","reviewer_value":"Test","type":"accidental_test_attestation_removed"},"reason":"Invocation de test de research-attest.mjs (--by=\"Test\") exécutée sans --apply obligatoire sur le dossier réel : elle a écrit une attestation humaine non légitime. Identifiant exact reconstitué et restauré en état révoqué (active=false). Correctif : research-attest.mjs passe en DRY-RUN strict par défaut (v0.3.3.1).","subject_id":"sha256:83064812b81e764649f4f7e81c55e2c047a92966068f2b1fe115419a76ec740b","subject_type":"context_attestation","tool_id":"wix"}],"tool_source_captures":[{"accessed_at":"2026-07-17T10:41:16.588Z","collector_id":"cap:e95314a0401055343d520f24f0a493522a164a28d0ccc209cccbc0eea7ab40e1","collector_payload":{"accessed_at":"2026-07-17T10:41:16.588Z","capture_id":"cap:e95314a0401055343d520f24f0a493522a164a28d0ccc209cccbc0eea7ab40e1","content_hash":"sha256:8278b53421e7b9c70fc957a99951accf4a897866215bbe1aac73b961dbd05a16","http_status":200,"is_accessible":true,"locale_evidence":{},"locale_proven":false,"market_context":null,"observed_locale":null,"observed_market":null,"rendered_by":"browser","text_len":16282,"version":1},"content_hash":"sha256:8278b53421e7b9c70fc957a99951accf4a897866215bbe1aac73b961dbd05a16","http_status":200,"is_accessible":true,"market_context":null,"notes":null,"observed_locale":null,"observed_market":null,"rendered_by":"browser","source_collector_id":"src:d39111fc783a7fc8d43696b4483ef03a8dd3e7ee1d25d4de0f1699aa604cdc8c","title":null},{"accessed_at":"2026-07-17T13:05:55.042Z","collector_id":"cap:0535f241de93f20420005cfefa0f6108785d64d435ab4975bcbeb9050be4e846","collector_payload":{"accessed_at":"2026-07-17T13:05:55.042Z","capture_id":"cap:0535f241de93f20420005cfefa0f6108785d64d435ab4975bcbeb9050be4e846","content_hash":"sha256:361999d5c076e32b3dc6bad6b959f10fb4d25e5d104bfbc98fc93182ba258c85","http_status":200,"is_accessible":true,"rendered_by":"static","text_len":4163,"version":1},"content_hash":"sha256:361999d5c07